def maximum(arr, k):
    if k == 0:
        return []
    if k == len(arr):
        candidates = arr[:]
    else:
        candidates = []
        used_indices = set()
        for _ in range(k):
            max_val = None
            max_idx = None
            for i, val in enumerate(arr):
                if i in used_indices:
                    continue
                if max_val is None or val > max_val:
                    max_val = val
                    max_idx = i
            used_indices.add(max_idx)
            candidates.append(max_val)
    for i in range(1, len(candidates)):
        key = candidates[i]
        j = i - 1
        while j >= 0 and candidates[j] > key:
            candidates[j + 1] = candidates[j]
            j -= 1
        candidates[j + 1] = key
    return candidates
