    @lru_cache(None)
    def count_sequences(length: int, start: int) -> int:
        if length == 1:
            return 1
        total = 0
        next_start = 2 * start
        if next_start > m:
            return 0
        for next_elem in range(next_start, m + 1):
            total += count_sequences(length - 1, next_elem)
        return total
    total_sequences = 0
    for first_elem in range(1, m + 1):
        total_sequences += count_sequences(n, first_elem)
    return total_sequences
