def find_solution(a: int, b: int, n: int):

    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        g, x1, y1 = extended_gcd(bb, aa % bb)
        x = y1
        y = x1 - aa // bb * y1
        return (g, x, y)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None
    x0 *= n // g
    y0 *= n // g
    a_div = a // g
    b_div = b // g
    from math import ceil
    k_min = ceil(-x0 / b_div) if b_div != 0 else 0
    if b_div == 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return None
    x_candidate = x0 + k_min * b_div
    y_candidate = y0 - k_min * a_div
    if x_candidate < 0:
        return None
    return (x_candidate, y_candidate)
