import re

def capital_words_spaces(text: str) -> str:
    tokens = re.findall('\\s+|\\S+', text)

    def split_cap_words(token):
        if not token or not token[0].isupper():
            return [token]
        parts = re.split('(?<!^)(?=[A-Z])', token)
        return parts
    result_tokens = []
    prev_was_space = True
    for token in tokens:
        if token.isspace():
            result_tokens.append(token)
            prev_was_space = True
        else:
            parts = split_cap_words(token)
            for i, part in enumerate(parts):
                if i > 0:
                    if not prev_was_space:
                        result_tokens.append(' ')
                result_tokens.append(part)
                prev_was_space = False
    return ''.join(result_tokens)
```

