def dif_Square(n: int) -> bool:
    if n == 0:
        return True
    abs_n = abs(n)
    for x in range(1, int(abs_n ** 0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            if x * y == n:
                if (x + y) % 2 == 0 and (y - x) % 2 == 0:
                    return True
            if y * x == n:
                if (y + x) % 2 == 0 and (x - y) % 2 == 0:
                    return True
            if -x * y == n:
                if (-x + y) % 2 == 0 and (y - -x) % 2 == 0:
