def find_solution(a: int, b: int, n: int):
    if a == 0:
        if b == 0:
            return (0, 0) if n == 0 else None
        if n % b == 0:
            y = n // b
            if y >= 0:
                return (0, y)
        return None
    if b == 0:
        if n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None
    from math import gcd
    g = gcd(a, b)
    if n % g != 0:
        return None

    def div_floor(x, y):
        if y == 0:
            raise ZeroDivisionError
        q, r = divmod(x, y)
        if r != 0 and (y < 0 and r > 0 or (y > 0 and r < 0)):
            q -= 1
        return q

    def div_ceil(x, y):
        if y == 0:
            raise ZeroDivisionError
        q, r = divmod(x, y)
        if r != 0:
            q += 1
        return q
    if b > 0:
        if a > 0:
            x_max = n // a
            x_min = 0
        elif a < 0:
            x_min = div_ceil(n, a)
            x_max = 10 ** 18
            if x_min < 0:
                x_min = 0
        else:
            return None
    elif a > 0:
        x_min = div_ceil(n, a)
        if x_min < 0:
            x_min = 0
        x_max = 10 ** 18
    elif a < 0:
        x_max = n // a
        x_min = 0
    else:
        return None
    abs_a = abs(a)
    abs_b = abs(b)
    if n >= 0:
        x_upper_bound = n // abs_a if abs_a != 0 else 0
        x_upper_bound += 10000
    else:
        x_upper_bound = 0
    if x_max > x_upper_bound:
        x_max = x_upper_bound
    if x_min < 0:
        x_min = 0
    for x in range(x_min, x_max + 1):
        numerator = n - a * x
        if numerator % b == 0:
            y = numerator // b
            if y >= 0:
                return (x, y)
    return None
