def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, 1 + dict_depth(v))
        elif isinstance(v, (list, tuple)):
            max_sub_depth = 0
            for item in v:
                if isinstance(item, dict):
                    max_sub_depth = max(max_sub_depth, dict_depth(item))
                elif isinstance(item, (list, tuple)):

                    def nested_depth(x):
                        if isinstance(x, dict):
                            return 1 + dict_depth(x)
                        elif isinstance(x, (list, tuple)):
                            return 1 + max((nested_depth(i) for i in x), default=0)
                        else:
                            return 0
                    max_sub_depth = max(max_sub_depth, nested_depth(item))
            max_depth = max(max_depth, 1 + max_sub_depth)
    return max_depth
