def get_total_number_of_sequences(n: int, m: int) -> int:
    dp = [1] * (m + 1)
    for length in range(2, n + 1):
        new_dp = [0] * (m + 1)
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            val = dp[x]
            if val == 0:
                continue
            start = 2 * x
            if start > m:
                continue
            prefix[start] += val
            prefix[m + 1] -= val
        running = 0
        for y in range(1, m + 1):
            running += prefix[y]
            new_dp[y] = running
        dp = new_dp
    return sum(dp[1:])
```

