    def extended_gcd(aa, bb):
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - aa // bb * y1
            return (g, x, y)
    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'
    x0 *= n // g
    y0 *= n // g
    b_div_g = b // g
    a_div_g = a // g
    if b_div_g == 0:
        if x0 >= 0:
            return (x0, y0)
        else:
            return 'No solution'
    from math import ceil, floor
    if b_div_g > 0:
        k = ceil(-x0 / b_div_g)
    else:
        k = floor(-x0 / b_div_g)
    x = x0 + k * b_div_g
    y = y0 - k * a_div_g
    if x < 0:
        return 'No solution'
    return (x, y)
