```python
def flatten_list(lst):
    result = []
    for item in lst:
        if isinstance(item, list):
            result.extend(flatten_list(item))
        else:
            result.append(item)
    return result
```

```python
def dict_depth(d):
    if not isinstance(d, dict) or not d:
        return 1
    return 1 + max((dict_depth(v) for v in d.values() if isinstance(v, dict)), default=0)
```

```python
def remove_column(matrix, col_idx):
    for row in matrix:
        if col_idx < 0 or col_idx >= len(row):
            raise IndexError('Column index out of range')
    return [row[:col_idx] + row[col_idx + 1:] for row in matrix]
```

```python
def min_flip_to_make_string_alternate(s: str) -> int:
    flips_start_with_0 = 0
    flips_start_with_1 = 0
    for i, char in enumerate(s):
        expected_char_0 = '0' if i % 2 == 0 else '1'
        expected_char_1 = '1' if i % 2 == 0 else '0'
        if char != expected_char_0:
            flips_start_with_0 += 1
        if char != expected_char_1:
            flips_start_with_1 += 1
    return min(flips_start_with_0, flips_start_with_1)
```

```python
def smallest_missing(arr):
    left, right = (0, len(arr) - 1)
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == mid:
            left = mid + 1
        elif arr[mid] > mid:
            right = mid - 1
        else:
            left = mid + 1
    return left
```

```python
def highest_Power_of_2(n: int) -> int:
    if n < 1:
        return 0
    power = 1
    while power <= n:
        power <<= 1
    return power >> 1
```

